BEGIN;
CREATE TABLE IF NOT EXISTS companies (company_id TEXT PRIMARY KEY,cnpj TEXT NOT NULL UNIQUE,legal_name TEXT NOT NULL,trade_name TEXT,email TEXT,whatsapp TEXT,city TEXT,state TEXT,status TEXT NOT NULL DEFAULT 'QUALIFIED' CHECK (status IN ('QUALIFIED','FOUNDER_ACTIVE','ACTIVE','SUSPENDED')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS founder_invites (invite_id TEXT PRIMARY KEY,invite_token TEXT NOT NULL UNIQUE,company_hint TEXT,model_hint TEXT,source TEXT,campaign TEXT,status TEXT NOT NULL DEFAULT 'INVITED' CHECK (status IN ('INVITED','OPENED','CONVERTED','EXPIRED','CANCELLED')),expires_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),opened_at TIMESTAMPTZ,converted_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS founder_applications (application_id TEXT PRIMARY KEY,access_token TEXT NOT NULL UNIQUE,company_id TEXT NOT NULL REFERENCES companies(company_id) ON DELETE RESTRICT,invite_id TEXT REFERENCES founder_invites(invite_id) ON DELETE SET NULL,model TEXT NOT NULL CHECK (model IN ('catalogo','servico','ambos')),status TEXT NOT NULL DEFAULT 'OFFERED' CHECK (status IN ('OFFERED','ACCEPTED','PENDING_PAYMENT','PAID','CONFIRMED','ONBOARDED','REJECTED','EXPIRED','CANCELLED')),adhesion_cents INTEGER NOT NULL CHECK (adhesion_cents >= 0),monthly_cents INTEGER NOT NULL DEFAULT 0 CHECK (monthly_cents >= 0),contact_name TEXT NOT NULL,contact_email TEXT NOT NULL,contact_whatsapp TEXT,accepted_at TIMESTAMPTZ,accepted_by_name TEXT,accepted_by_email TEXT,accepted_ip TEXT,accepted_user_agent TEXT,acceptance_version TEXT,founder_slot SMALLINT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS founder_applications_one_open_per_company ON founder_applications(company_id) WHERE status IN ('OFFERED','ACCEPTED','PENDING_PAYMENT','PAID','CONFIRMED','ONBOARDED');
CREATE TABLE IF NOT EXISTS founder_slots (slot_no SMALLINT PRIMARY KEY CHECK (slot_no BETWEEN 1 AND 54),company_id TEXT UNIQUE REFERENCES companies(company_id) ON DELETE RESTRICT,application_id TEXT UNIQUE REFERENCES founder_applications(application_id) ON DELETE RESTRICT,confirmed_at TIMESTAMPTZ);
INSERT INTO founder_slots(slot_no) SELECT value FROM generate_series(1,54) AS value ON CONFLICT(slot_no) DO NOTHING;
CREATE TABLE IF NOT EXISTS founder_payments (payment_id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES founder_applications(application_id) ON DELETE RESTRICT,company_id TEXT NOT NULL REFERENCES companies(company_id) ON DELETE RESTRICT,provider TEXT NOT NULL,provider_payment_id TEXT UNIQUE,external_reference TEXT NOT NULL UNIQUE,amount_cents INTEGER NOT NULL CHECK(amount_cents>=0),status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','PAID','FAILED','EXPIRED','CANCELLED','REFUNDED')),qr_code TEXT,qr_code_base64 TEXT,ticket_url TEXT,provider_status TEXT,provider_status_detail TEXT,provider_payload JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),paid_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS founder_payments_application_idx ON founder_payments(application_id,created_at DESC);
CREATE TABLE IF NOT EXISTS founder_events (event_id BIGSERIAL PRIMARY KEY,application_id TEXT REFERENCES founder_applications(application_id) ON DELETE CASCADE,company_id TEXT REFERENCES companies(company_id) ON DELETE CASCADE,event_type TEXT NOT NULL,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS founder_events_application_idx ON founder_events(application_id,created_at DESC);
CREATE TABLE IF NOT EXISTS company_onboarding (company_id TEXT PRIMARY KEY REFERENCES companies(company_id) ON DELETE CASCADE,application_id TEXT NOT NULL REFERENCES founder_applications(application_id) ON DELETE RESTRICT,model TEXT NOT NULL CHECK(model IN ('catalogo','servico','ambos')),payload JSONB NOT NULL,completed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
COMMIT;
